//! The VPy builtins as the compiler has them: `builtins_catalog.json`, generated by
//! vpy_cli from its code generators and docs/MANUAL.md (vpy_cli builtins_catalog.rs,
//! whose test fails while this copy is out of date). Names, signatures, doc lines and
//! the targets each builtin exists on.

use std::collections::HashMap;
use std::sync::OnceLock;

#[derive(Debug, Clone)]
pub struct Builtin {
    pub name: String,
    /// Every documented form (`PRINT_TEXT(x, y, text)`, the 5-argument one…); an alias
    /// (`MATH_SIN`) has those of the builtin it stands for.
    pub signatures: Vec<String>,
    pub doc: Option<String>,
    pub targets: Vec<String>,
}

static CATALOG: OnceLock<HashMap<String, Builtin>> = OnceLock::new();

fn catalog() -> &'static HashMap<String, Builtin> {
    CATALOG.get_or_init(|| {
        let json: serde_json::Value =
            serde_json::from_str(include_str!("builtins_catalog.json")).expect("builtins_catalog.json");
        let strs = |v: Option<&serde_json::Value>| -> Vec<String> {
            v.and_then(|a| a.as_array())
                .map(|a| a.iter().filter_map(|x| x.as_str().map(str::to_string)).collect())
                .unwrap_or_default()
        };
        let mut out = HashMap::new();
        let mut aliases = Vec::new();
        for b in json["builtins"].as_array().into_iter().flatten() {
            let name = b["name"].as_str().unwrap_or_default().to_string();
            let mut signatures: Vec<String> = b["signature"].as_str().map(|s| vec![s.to_string()]).unwrap_or_default();
            signatures.extend(strs(b.get("alternatives")));
            if let Some(a) = b["aliasOf"].as_str() {
                aliases.push((name.clone(), a.to_string()));
            }
            out.insert(
                name.to_ascii_uppercase(),
                Builtin { name, signatures, doc: b["doc"].as_str().map(str::to_string), targets: strs(b.get("targets")) },
            );
        }
        // An alias documents nothing of its own: it is the other builtin under another name
        for (alias, of) in aliases {
            if let Some(target) = out.get(&of.to_ascii_uppercase()).cloned() {
                let a = out.get_mut(&alias.to_ascii_uppercase()).unwrap();
                if a.signatures.is_empty() {
                    a.signatures = target.signatures.iter().map(|s| s.replacen(&target.name, &a.name, 1)).collect();
                }
                if a.doc.is_none() {
                    a.doc = target.doc.map(|d| format!("{d} (alias of {})", target.name));
                }
            }
        }
        out
    })
}

/// The builtin `name` (any case), if the compiler has one.
pub fn lookup(name: &str) -> Option<&'static Builtin> {
    catalog().get(&name.to_ascii_uppercase())
}

/// Every builtin, for completion.
pub fn all() -> impl Iterator<Item = &'static Builtin> {
    catalog().values()
}

/// How many arguments a signature takes: `f(a, b[, c[, d]])` takes 2, 3 or 4,
/// `f(a[, x, y, z])` 1 or 4. None for a variable count (`...`).
pub fn arg_counts(signature: &str) -> Option<Vec<usize>> {
    let open = signature.find('(')?;
    let close = signature.rfind(')')?;
    let inner = &signature[open + 1..close];
    if inner.contains("...") || inner.contains('…') {
        return None;
    }
    // Each parameter's depth inside [ ]: a group adds its parameters all at once
    let mut depth = 0usize;
    let mut by_depth: Vec<usize> = vec![0];
    let mut in_param = false;
    let mut quote = false;
    for ch in inner.chars() {
        match ch {
            '"' => { quote = !quote; if !in_param { in_param = true; by_depth[depth] += 1; } }
            _ if quote => {}
            '[' => { depth += 1; if by_depth.len() <= depth { by_depth.push(0); } in_param = false; }
            ']' => { depth = depth.saturating_sub(1); in_param = false; }
            ',' => in_param = false,
            c if c.is_whitespace() => {}
            _ => { if !in_param { in_param = true; by_depth[depth] += 1; } }
        }
    }
    let mut counts = Vec::new();
    let mut n = 0;
    for k in by_depth {
        n += k;
        counts.push(n);
    }
    counts.dedup();
    Some(counts)
}

/// Every argument count the builtin accepts, over all its forms; None when any form
/// takes a variable count (or none is documented).
pub fn accepted_counts(b: &Builtin) -> Option<Vec<usize>> {
    if b.signatures.is_empty() {
        return None;
    }
    let mut all = Vec::new();
    for s in &b.signatures {
        all.extend(arg_counts(s)?);
    }
    all.sort_unstable();
    all.dedup();
    Some(all)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn signatures_give_the_argument_counts() {
        assert_eq!(arg_counts("DRAW_LINE(x0, y0, x1, y1, intensity)"), Some(vec![5]));
        assert_eq!(arg_counts("GET_FRAME_US()"), Some(vec![0]));
        assert_eq!(arg_counts(r#"DRAW_ANIM("name", x, y[, mirror[, scale[, speed]]])"#), Some(vec![3, 4, 5, 6]));
        assert_eq!(arg_counts("CAMERA_LOOK_AT(ex, ey, ez, tx, ty, tz[, ux, uy, uz])"), Some(vec![6, 9]));
        assert_eq!(arg_counts("DRAW_POLYGON(n, intensity, x0, y0, ..., xn-1, yn-1)"), None);
        assert_eq!(arg_counts(r#"PRINT_TEXT(x, y, "a, b")"#), Some(vec![3]));
    }

    #[test]
    fn the_catalog_has_the_compilers_builtins() {
        assert!(all().count() > 200);
        let arc = lookup("draw_arc").unwrap();
        assert_eq!(accepted_counts(arc), Some(vec![7]));
        assert!(lookup("MESH_OCCLUSION").unwrap().targets.iter().any(|t| t == "uvm2"));
        // an alias borrows the builtin's signature
        assert!(!lookup("MATH_SIN").unwrap().signatures.is_empty());
        assert!(lookup("RECT").is_none(), "not a VPy builtin");
    }
}
